const KEY='moneyLabDuet.v1',app=document.querySelector('#app');let d=createDuel(),lang='vi',busy=false,verified=false,error='',confirmAbort=false;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.version===1&&saved.players?.length>=2&&saved.players.length<=6&&saved.players.every(p=>p.hub&&(!p.game||p.game.version===2)))d=saved;lang=localStorage.getItem('moneyLabLanguage')==='en'?'en':'vi';}catch{}
const vi=()=>lang==='vi',tr=(a,b)=>vi()?a:b,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
function save(){try{localStorage.setItem(KEY,JSON.stringify(d));}catch{error=tr('Không lưu được trên thiết bị.','Device saving unavailable.');}}
const btn=(text,a,disabled=false)=>`<button data-a="${a}" ${busy||disabled?'disabled':''}>${text}</button>`;
const coords=[[1,1],[1,2],[1,3],[1,4],[1,5],[2,5],[3,5],[4,5],[5,5],[5,4],[5,3],[5,2],[5,1],[4,1],[3,1],[2,1]];
const names={vi:{start:'Khởi đầu',opportunity:'Cơ hội',expense:'Bất ngờ',learn:'Kiến thức',market:'Thị trường',salary:'Thu nhập'},en:{start:'Start',opportunity:'Opportunity',expense:'Unexpected',learn:'Knowledge',market:'Market',salary:'Income'}};
function eventCard(s){if(s.route)return `<h2>${tr('Chọn đường đi','Choose your route')}</h2><p>${tr('Cùng một nhóm sự kiện và hai vị trí cho mọi người. Chọn một ô trước khi biết tình huống cụ thể.','Everyone gets the same event category and two spaces. Choose one before its specific scenario is revealed.')}</p>${routeChoicesHTML(s,lang,'data-a','route-',busy)}`;const e=s.pending;if(!e)return `${monthlyHTML(s.last,lang)}${lessonHTML(s.last,lang,false)}<h2>${tr('Chuẩn bị lượt của bạn','Prepare your turn')}</h2><p>${tr('Quản lý tiền, gieo hai lựa chọn rồi chọn một đường đi. Mọi người dùng cùng nhóm sự kiện và điểm đến mỗi tháng.','Manage your money, roll two options, then choose one route. All players share each month’s category and destinations.')}</p>${btn(tr('Gieo xúc xắc →','Roll the dice →'),'roll')}`;
 let html=`${monthlyHTML(e,lang)}<span class="card-kicker">${tr('THÁNG','MONTH')} ${s.month} / 12</span>`;
 if(e.monthly?.surcharge)html+=`<p class="income-shock">${tr('Chi phí bắt buộc theo cấp','Mandatory level pressure')}: ${money(e.monthly.surcharge)}</p>`;
 if(e.monthly?.incomeCut)html+=`<p class="income-shock">${tr('Giảm thu nhập','Income cut')}: ${money(e.monthly.incomeCut)}</p>`;
 if(e.type==='learn'){const q=question(e.questionId);if(!q)return html+`<p>${tr('Đã hoàn thành bộ câu hỏi.','Question bank completed.')}</p>${btn(tr('Tiếp tục','Continue'),'continue')}`;const c=q[lang];return html+`<h2>${esc(c[0])}</h2>${[0,1].map(i=>btn(esc(c[i===e.answerOrder?1:2]),'answer-'+i)).join('')}`;}
 if(e.type==='opportunity'){const o=opportunity(e.eventId);return html+`<h2>${esc(o[lang][0])}</h2><p>${esc(o[lang][1])}</p><h3>${money(o.cost)}</h3>${btn(tr('Tham gia','Invest'),'buy',s.cash<o.cost||s.gate.OUT0===0)}${btn(tr('Bỏ qua','Pass'),'skip')}`;}
 if(e.type==='expense'){const x=surprise(e.eventId);return html+`<h2>${esc(x[lang][0])}</h2><p>${esc(x[lang][1])}</p><h3>${x.income?'+':'−'}${money(x.income||(x.optional?x.cost:essentialCost(s,x.cost)))}</h3>${x.optional?btn(tr('Chọn mua','Buy'),'spend',s.cash<x.cost)+btn(tr('Bỏ qua','Pass'),'skip'):btn(x.income?tr('Nhận tiền','Receive funds'):tr('Thanh toán','Pay'),'pay')}`;}
 if(e.type==='market'){const x=marketStory(e.marketId),kinds=[...new Set(s.positions.map(p=>p.kind))];return html+`<h2>${esc(x?.[lang][0]||tr('Biến động thị trường','Market event'))}</h2><p>${esc(x?.[lang][1]||'')}</p>${kinds.map(k=>`<p>${CATEGORY_NAMES[lang][k]}: ${Number((marketRate(s,x?.rates[k]??MARKET_RATES[k][e.variant])*100).toFixed(2))}%</p>`).join('')}${btn(tr('Áp dụng sự kiện','Apply event'),'continue')}`;}
 return html+`${e.type==='salary'?jobHTML(e,lang):`<h2>${tr('Qua khởi đầu: +$300','Start bonus: +$300')}</h2>`}${btn(tr('Nhận và tiếp tục','Collect and continue'),'continue')}`;
}
function render(){const entering=d.active&&!document.body.classList.contains('is-playing');document.body.classList.toggle('is-playing',d.active);document.documentElement.lang=lang;const level=LEVELS[d.level];let html=`${tokenRoadmap(lang)}<section class="intro"><div><p class="eyebrow">MONEY LAB / DUET & GROUP</p><h1>${tr('Cùng tình huống. Khác quyết định.','Same scenario. Different decisions.')}</h1><p>${tr('2–6 người luân phiên trên cùng thiết bị, cùng cấp độ và lựa chọn xúc xắc. Phải thắng chặng Hub trước khi được xét thắng cược. Đây chưa phải phòng online.','2–6 players take turns on one device at the same level with shared rolls. Clear your Hub stage before you can win the wager. This is not an online room.')}</p></div></section><p><a class="duel-link" href="./online.html">${tr('Chơi online · mỗi người một thiết bị →','Play online · separate devices →')}</a></p><section class="quick-guide">${quickGuide(lang)}</section><section class="competition-summary">${wagerRulesHTML(lang)}<p><b>${tr('Thắng Hub trước. Thắng cược sau.','Clear Hub first. Compete second.')}</b> ${tr('Dễ cược 10 · Trung bình 40 · Khó 80 HUB/người. Không thu thêm cam kết Hub. Top ⌈N/2⌉ chỉ xét người qua Hub. Người thua mất cược: 50% chia theo điểm người thắng, 50% vào công quỹ.','Stake per player: Easy 10 · Medium 40 · Hard 80 HUB. No extra Hub commitment. Top ⌈N/2⌉ considers Hub clears only. Losers forfeit stakes: 50% pays winners by score, 50% enters the treasury.')}</p><details><summary>${tr('Công quỹ & trường hợp đặc biệt','Treasury & special cases')}</summary><p>${tr('Công quỹ mô phỏng trên thiết bị','Device-local fictional treasury')}: <b>${d.treasury?.balance||0} HUB</b> · ${tr('Quỹ thưởng chờ','Unclaimed prize pool')}: <b>${d.treasury?.carry||0} HUB</b></p><p>${tr('Không đủ người qua Hub thì để trống suất thắng. Nếu không có người thắng cược: 50% vào công quỹ, 50% chuyển quỹ thưởng chờ cho trận sau có người thắng. Bằng điểm xét tài sản ròng rồi dự phòng; vẫn bằng nhau ở ranh giới thắng thì nhóm đồng hạng hòa cược, hoàn cược. HUB giả lập, không đổi tiền thật.','Unfilled winning slots stay empty. If nobody wins the wager, half the forfeited pot goes to the treasury and half carries to the next match with winners. Ties use net worth then reserves; a complete tie at the winning cutoff refunds the tied seats. HUB is fictional and not redeemable.')}</p>${(d.treasury?.history||[]).map(r=>`<p>#${r.round} · ${r.players} ${tr('người','players')} · +${r.contribution} ${tr('công quỹ','treasury')} · ${r.payout} ${tr('thưởng cược','wager payout')} · ${r.carryOut} ${tr('chờ','carry')}</p>`).join('')}</details></section><div class="duet-players">${d.players.map((p,i)=>`<div class="player-panel ${d.active&&d.turn===i?'selected':''}"><strong>${esc(p.name)}</strong><p>${p.hub.balance} HUB · ${tr('Cam kết','Committed')} ${p.stake||p.hub.active?.bond||0}</p>${p.game?`<p>${tr('Tháng','Month')} ${p.game.month}/12 · ${money(netWorth(p.game))} · ${p.game.phase==='finished'?score(p.game).total+'/100':tr('Đang chơi','In progress')}</p>`:''}</div>`).join('')}</div>`;
 if(d.active&&!d.betRules)html+=`<p class="warning">${tr('Trận lưu từ bản cũ đang dùng luật cũ, không thu cược hồi tố. Bắt đầu trận tiếp theo để dùng luật cược mới.','This legacy saved match keeps its original rules with no retroactive stakes. New wager rules begin with your next match.')}</p>`;
 if(error)html+=`<p class="warning">${esc(error)}</p>`;
 if(d.done){if(d.betResult){const r=d.betResult;html+=`<section class="decision match-results"><p class="eyebrow">${tr('KẾT TOÁN TRẬN','MATCH SETTLEMENT')} #${d.round}</p><h2>${r.winners.length?tr('Người thắng cược: ','Wager winners: ')+r.winners.map(i=>esc(d.players[i].name)).join(', '):r.draws.length?tr('Hòa cược ở ranh giới thắng','A draw at the winning cutoff'):tr('Không ai vượt qua thử thách Hub','Nobody cleared the Hub challenge')}</h2><p>${tr('Thưởng Hub độc lập với thắng/thua cược. Người qua Hub nhưng ngoài suất thắng cược vẫn nhận thưởng Hub bình thường.','Hub rewards are independent of wager results. A Hub clear outside the winning seats still earns its normal Hub reward.')}</p><div class="settlement-table-wrap"><table class="settlement-table"><thead><tr>${(vi()?['Người chơi','Điểm / Hub','Cược đã khóa','Hoàn cược','Thưởng Hub','Thưởng cược','Mất cược','Số dư cuối']:['Player','Score / Hub','Stake locked','Stake returned','Hub reward','Wager reward','Stake lost','Final balance']).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${r.rows.map(x=>`<tr><th>${esc(d.players[x.index].name)}<small>${x.status==='won'?tr('Thắng cược','Wager win'):x.status==='draw'?tr('Hòa cược','Wager draw'):tr('Thua cược','Wager loss')}</small></th><td>${x.points}/100 · ${x.hubWon?tr('Qua Hub','Hub cleared'):tr('Trượt Hub','Hub failed')}</td><td>${x.stake}</td><td>${x.refund}</td><td>+${x.hubReward}</td><td>+${x.betReward}</td><td>−${x.betLoss}</td><td>${d.players[x.index].hub.balance} HUB</td></tr>`).join('')}</tbody></table></div><p>${tr('Tổng cược thua','Forfeited stakes')}: ${r.losingPot} HUB = ${r.treasury} ${tr('vào công quỹ','to treasury')} + ${r.losingPot-r.treasury} ${tr('vào quỹ thưởng','to prize pool')}. ${tr('Quỹ thưởng chờ đưa vào','Previous carry')}: ${r.carryIn}. ${tr('Đã chia','Paid')}: ${r.rows.reduce((n,x)=>n+x.betReward,0)}. ${tr('Chờ trận sau','Carry forward')}: ${r.carryOut} HUB.</p><p class="hub-fine">${tr('Thưởng cược chia theo tỷ lệ điểm; HUB nguyên dùng phần dư lớn nhất để tổng chia đúng quỹ.','Wager rewards are proportional to winner scores; largest remainders allocate whole HUB without losing any pool balance.')}</p>${progressionHTML(roomProgression(d.level,d.players),lang)}${btn(tr('Tiếp trận kế tiếp','Next match'),'next-match')}</section>`;}else{const winner=duelRanking(d);html+=`<section class="decision"><h2>${winner===-1?tr('Hòa nhau!','A draw!'):esc(d.players[winner].name)+' '+tr('thắng đối đầu!','wins the duel!')}</h2><p>${tr('Trận lưu từ bản cũ: không áp dụng cược mới hồi tố.','A legacy saved match: new wager rules are not applied retroactively.')}</p>${progressionHTML(roomProgression(d.level,d.players),lang)}${btn(tr('Tiếp trận kế tiếp','Next match'),'next-match')}</section>`;}}
 else if(!d.active){html+=`${financialDashboard(createGame(d.level),lang)}<section class="decision"><h2>${tr('Chuẩn bị duet / nhóm','Set up duet / group')} · ${level[lang][0]}</h2><p>${tr('Mỗi hồ sơ bắt đầu 80 HUB, tách solo. Tất cả phải mở khóa cùng cấp và đủ cược. Thay đổi số người vẫn giữ hồ sơ của các ghế đã tạo.','Each profile starts with 80 HUB, separate from solo. Every player must unlock the same level and afford its stake. Changing the player count preserves existing seat profiles.')}</p><div class="player-count" role="group" aria-label="Player count">${[2,3,4,5,6].map(n=>btn(`${n} ${tr('người','players')}${d.players.length===n?' ✓':''}`,'count-'+n)).join('')}</div><div class="duet-names">${d.players.map((p,i)=>`<label>${tr('Tên người chơi','Player name')} ${i+1}<input id="name${i}" maxlength="24" ${busy?'disabled':''} value="${esc(p.name)}"></label>`).join('')}</div><div class="level-grid">${Object.values(LEVELS).map(l=>btn(`${l[lang][0]} · ${matchStake(l.id)} HUB / ${tr('người','player')}`,'start-'+l.id,!d.players.every(p=>unlocked(p.hub,l.id)&&p.hub.balance>=matchStake(l.id)))).join('')}</div></section>`;}
 else{const p=d.players[d.turn],s=p.game;html+=`<div class="duet-layout play-columns play-workspace"><section class="board-panel match-board-panel">${matchBoard(d.players,d.turn,d.turn,lang)}<div class="stats duet-stats"><div>${tr('Tiền mặt','Cash')}<b>${money(s.cash)}</b></div><div>${tr('Dự phòng','Reserve')}<b>${money(s.reserve)}</b></div><div>${tr('Đầu tư','Investments')}<b>${money(s.investments)}</b></div><div>${tr('Nợ','Debt')}<b>${money(debt(s))}</b></div></div>${s.phase==='ready'&&!s.route?`<div class="duet-manage">${btn(tr('Dự phòng +500','Reserve +500'),'manage-reserve',s.cash<500)}${btn(tr('Rút dự phòng 500','Release reserve 500'),'manage-release',s.reserve<500)}${btn(tr('Quỹ ML-100: 1.000','ML-100 fund: 1,000'),'manage-invest',s.cash<1000||s.gate.OUT0===0)}${btn(tr('Bán tối đa 1.000','Sell up to 1,000'),'manage-sell',sellable(s)===0)}</div>`:''}<small>${tr('Vốn kinh doanh và bất động sản khóa bán trong chặng.','Business and property capital are locked for the stage.')}</small></section><section class="decision">${turnClockHTML(s,lang)}<p class="eyebrow">${esc(p.name)} · ${level[lang][0]}</p>${eventCard(s)}<p class="hub-fine">TapeOut #48 · ${p.receipt?`${tr('Đã đọc khối','Read at block')} ${p.receipt.blockNumber} · OUT ${p.receipt.OUT0}`:tr('Kết quả sẽ đọc khi xác nhận quyết định.','The circuit is read when a decision is confirmed.')}</p>${btn(tr('Bỏ trận','Abandon match'),'abort')}</section>${compactFinancialDashboard(s,lang)}</div>`;
 if(d.handoff)html+=`<div class="handoff"><section class="decision">${turnClockHTML(s,lang)}<span class="eyebrow">${tr('CHUYỂN THIẾT BỊ','PASS THE DEVICE')}</span><h2>${tr('Đến lượt','Your turn,')} ${esc(p.name)}</h2>${d.lastFeedback?`<p>${esc(d.lastFeedback[lang])}</p>`:''}<p>${tr('Hãy đưa thiết bị cho người tiếp theo trước khi mở lượt.','Pass the device to the next player before opening the turn.')}</p>${btn(tr('Tôi đã sẵn sàng','I am ready'),'ready')}</section></div>`;
 }
 if(confirmAbort)html+=`<div class="handoff"><section class="decision"><h2>${tr('Bỏ trận đối đầu?','Abandon this duel?')}</h2><p>${tr('Mọi ghế chưa hoàn thành bị tính trượt Hub và thua cược. Ghế đã qua Hub vẫn được xét thưởng/cược. Trận được kết toán ngay; không thể hoàn tác.','Every unfinished seat fails Hub and forfeits its stake. Completed Hub clears retain eligibility and rewards. The match settles immediately; this cannot be undone.')}</p>${btn(tr('Xác nhận bỏ trận','Confirm abandonment'),'confirm-abort')}${btn(tr('Tiếp tục chơi','Keep playing'),'cancel-abort')}</section></div>`;
 html+=`<p class="hub-fine">${busy?tr('Đang đọc X Layer…','Reading X Layer…'):verified?tr('Mạch đã xác minh · Không ký ví · HUB giả lập','Circuit verified · No wallet signing · Fictional HUB'):tr('Chưa xác minh mạch.','Circuit not yet verified.')}</p>`;app.innerHTML=html;if(entering)requestAnimationFrame(()=>document.querySelector('.play-workspace')?.scrollIntoView({block:'start'}));document.querySelectorAll('.play-columns>.decision').forEach(el=>compactDecision(el,lang,d.players[d.turn]?.game));mountRiskPanel(!d.handoff?d.players[d.turn]?.game:null,lang,{container:'#matchRiskPreflight',source:'local-multiplayer'});updateDecisionLab(!d.handoff?d.players[d.turn]?.game:null,lang,{container:'#matchDecisionLab'});
}
async function action(a){if(busy)return;if(a!=='timeout'&&d.active&&turnExpired(d.players[d.turn].game)){await action('timeout');return;}if(a.startsWith('count-')){if(resizeDuel(d,Number(a.slice(6)))){save();render();}return;}if(a==='ready'){d.handoff=false;save();render();return;}if(a==='abort'){confirmAbort=true;render();return;}if(a==='cancel-abort'){confirmAbort=false;render();return;}if(a==='next-match'){if(!d.done)return;d.level=roomProgression(d.level,d.players).level;d.done=false;save();render();return;}
 const candidate=structuredClone(d);let index=candidate.turn;
 if(a==='timeout'){if(!timeoutDuel(candidate))return;index=d.turn;}
 else if(a.startsWith('start-')){candidate.players.forEach((p,i)=>p.name=document.querySelector('#name'+i).value.trim().slice(0,24)||'Player '+(i+1));const seed=crypto.getRandomValues(new Uint32Array(1))[0];if(!startDuel(candidate,a.slice(6),seed))return;index=0;}
 else if(a==='confirm-abort'){if(!abandonDuel(candidate))return;}
 else {const s=candidate.players[index].game,e=s.pending;if(!duelAct(candidate,a))return;if(e?.type==='learn'&&s.last?.questionId){const q=question(s.last.questionId);const revealed=candidate.players.every((p,i)=>i===index||p.game.phase==='finished'||p.game.month>s.last.month||p.game.history.some(r=>r.month===s.last.month));candidate.lastFeedback=revealed?{vi:`${candidate.players[index].name}: ${s.last.correct?'Đúng':'Chưa đúng'}. ${q.vi[3]}`,en:`${candidate.players[index].name}: ${s.last.correct?'Correct':'Not quite'}. ${q.en[3]}`}:{vi:'Đã ghi nhận câu trả lời. Đáp án được công bố sau khi tất cả hoàn thành lượt.',en:'Answer recorded. The explanation is revealed after all players finish this turn.'};}else candidate.lastFeedback=null;}
 busy=true;error='';render();try{if(!verified){await verifyCircuit();verified=true;}if(candidate.active||candidate.done){const p=candidate.players[index],s=p.game;if(s){const receipt=await evaluateGate(s.gate.IN0,s.gate.IN1);s.gate={IN0:receipt.IN0,IN1:receipt.IN1,OUT0:receipt.OUT0};recordGateProof(s,receipt);p.receipt=receipt;}}trackLocal(d,candidate);d=candidate;confirmAbort=false;save();}catch(e){error=tr('Không đọc được mạch. Quyết định chưa được áp dụng. Thử lại.','Circuit read failed. Your decision was not applied. Please retry.');}finally{busy=false;render();}}
app.addEventListener('input',e=>{if(/^name[0-5]$/.test(e.target.id)){d.players[Number(e.target.id.slice(-1))].name=e.target.value.slice(0,24);save();}});app.addEventListener('click',e=>{const a=e.target.closest('[data-a]')?.dataset.a;if(a)action(a);});for(const l of ['vi','en'])document.querySelector('#'+l).onclick=()=>{lang=l;try{localStorage.setItem('moneyLabLanguage',l);}catch{}render();};
render();busy=true;render();verifyCircuit().then(()=>verified=true).catch(()=>error=tr('Chưa kết nối được X Layer. Bạn có thể thử lại khi bắt đầu.','X Layer is unavailable. Retry when starting.')).finally(()=>{busy=false;render();});

mountProgressReset();

mountSoundtrack(()=>d.players[d.turn]?.game);



if(d.active&&!Number.isFinite(d.players[d.turn].game.turnDeadline)){armTurn(d.players[d.turn].game);save();render();}
mountTurnTicker(async()=>{if(!busy&&d.active)await action('timeout');});

mountAnalytics();
